llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Sacubitril absolute oral bioavailability was estimated as 60% in healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Letermovir absolute oral bioavailability was estimated as 93.8% in healthy participants using a population PK model with oral and i.v. data, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Idasanutlin absolute oral bioavailability was 40.1% in patients with solid tumors after a single oral dose with IV tracer, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All molecule-level evidence supports high oral bioavailability at the F ≥ 20% threshold; numeric absolute/systemic bioavailability values range from about 34% to 99%, and the only sub-threshold record is a fed-state special formulation for idasanutlin that is outweighed by its ordinary-condition 40.1% value.",
  "evidence_gaps": [
    "The only sub-threshold record (idasanutlin 18.7%) is from a fed-state MBP formulation, so its relevance to ordinary oral conditions is uncertain.",
    "Some supporting records are qualitative ('good', 'high') rather than numeric threshold measurements, but they are consistent with the numeric evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

